var BLN_LINES=['https://www.bilinovel.net','https://bilinovel.net','https://w.linovelib.com'];
var BLN_TAG=['主域·直出内容','301入口→主域','301入口→主域'];

function BLN_gv(k){var v='';
  try{v=String(source.get(k)||'')}catch(e){}
  if(!v||v=='null'){try{var st=String(source.getVariable()||'');if(st){var o=JSON.parse(st);v=String(o[k]||'')}}catch(e2){}}
  if(!v||v=='null'){try{v=String(java.get(k)||'')}catch(e3){}}
  if(!v||v=='null'){try{v=String(cache.get(k)||'')}catch(e4){}}
  if(v=='undefined')v='';return v;}
function BLN_norm(h){var m=String(h||'').match(/^(https?:\/\/[^\/]+)/);return m?m[1]:'';}
function BLN_short(h){return String(h||'').replace(/^https?:\/\//,'');}
function BLN_H(){var h=BLN_norm(BLN_gv('blnHost'));return h?h:'https://www.bilinovel.net';}
function BLN_w(h){h=BLN_norm(h)||'https://www.bilinovel.net';
  try{source.put('blnHost',h)}catch(e0){}
  try{var o={},v=String(source.getVariable()||'');try{o=v?(JSON.parse(v)||{}):{}}catch(e1){o={}}o.blnHost=h;source.setVariable(JSON.stringify(o))}catch(e2){}
  try{java.put('blnHost',h)}catch(e3){}
  try{cache.put('blnHost',h)}catch(e4){}return h;}
function BLN_toast(t){try{java.toast(t)}catch(e){try{java.longToast(t)}catch(e2){}}}
function BLN_curText(){return '当前线路 '+BLN_short(BLN_H());}
function BLN_lineBtn(i){var L=BLN_LINES[i];var sp=BLN_gv('blnsp'+i);var tg=BLN_TAG[i]||'';
  return (BLN_H()==L?'✅ ':'⬜ ')+BLN_short(L)+(tg?'\n'+tg:'')+(sp?'\n'+sp:'');}
