ruleContent.content:
@js:
(function(){
  // ===== 正文段落错位修复 v4（两种乱序统一正解）=====
  // 站点 chapterlog.js 给"非浏览器"返回混入隐藏干扰段的正文：
  //   服务端在 <head> 注入 CSS: #acontent p[data-kXXX]{position:absolute;transform:scale(0)}
  //   浏览器按 CSS 隐藏这些段后顺序正确；Legado ajax 拿不到 CSS → 看到乱序/重复。
  // 正解：用 webView+webJs 在浏览器里读取 CSS 规则、删除被隐藏 p，返回干净 HTML。
  // 已实测：正文章 /novel/2353/83408.html(107段,三四间距3285→62) 与
  //         插图章 /novel/8/114783.html(31段→30段简介全顺) 均一次请求修复。
  var full = String(result || '');
  function cleanHtml(html){
    html = String(html||'');
    html = html.replace(/\sdata-k\d+=""/g, '');
    html = html.replace(/data-src="([^"]+)"/g, 'src="$1"');
    html = html.replace(/src="\/images\/sloading\.svg"/g, '');
    html = html.replace(/style="display:none;"/g, '');
    // 去掉混入的 Google 广告脚本节点
    html = html.replace(/<script[\s\S]*?<\/script>/g, '');
    html = html.replace(/\(adsbygoogle\s*=\s*window\.adsbygoogle\s*\|\|\s*\[\]\)\.push\(\{\}\);?/g, '');
    html = html.replace(/<p>\s*<\/p>/g, '');
    return html;
  }
  var doc0 = org.jsoup.Jsoup.parse(full);
  var e0 = doc0.select('#acontent').first();
  var h0 = cleanHtml(e0 ? e0.html() : '');
  // 从 result 的 ReadParams 拼当前页 URL（跟随线路，不写死域名）
  var hm=(full.match(/url_home:'([^']*)'/)||[,''])[1].replace(/\/+$/,'');
  var aid=(full.match(/articleid:'([^']*)'/)||[,''])[1];
  var cid=(full.match(/chapterid:'([^']*)'/)||[,''])[1];
  var pg =(full.match(/page:'([^']*)'/)||[,'1'])[1];
  if(hm && aid && cid){
    var cur=hm+'/novel/'+aid+'/'+cid+(parseInt(pg)>1?'_'+pg:'')+'.html';
    var WJS = "(function(){var hid={};for(var k=0;k<document.styleSheets.length;k++){try{var rs=document.styleSheets[k].cssRules;for(var j=0;j<rs.length;j++){var css=rs[j].cssText||\"\";var mm=css.match(/data-k(\\d+)[^}]*scale\\(0\\)/);if(mm)hid[mm[1]]=1;}}catch(e){}}var ac=document.getElementById(\"acontent\");if(!ac)return \"NOAC\";var ps=ac.querySelectorAll(\"p\");for(var i=ps.length-1;i>=0;i--){var p=ps[i],dk=\"\";for(var a=0;a<p.attributes.length;a++){var nm=p.attributes[a].name;if(nm.indexOf(\"data-k\")===0)dk=nm.substring(6);}if(hid[dk])p.parentNode.removeChild(p);}return ac.innerHTML;})()";
    var opt = ',{"webView":true,"webViewDelayTime":500,"webJs":' + JSON.stringify(WJS) + '}';
    var wv='';
    try{ wv=String(java.ajax(cur+opt)); }catch(e){}
    // webJs 返回干净 #acontent HTML（已剔除隐藏干扰段）
    if(wv && wv.length>200 && wv.indexOf('<p')>=0 && wv.indexOf('NOAC')<0){
      var h1 = cleanHtml(wv);
      if(h1.length>200) return h1;
    }
  }
  // webView 失败兜底：退回普通解析（至少不崩）
  return h0;
})()

