ruleSearch.bookList:
@js:(function(){
  var body = String(result || '');
  function refetch() {
    var u = ''; try { u = String(java.get('blnUrl') || ''); } catch (e0) {}
    if (!u || u == 'null') { u = String(baseUrl); }
    try { Packages.java.lang.Thread.sleep(5300); } catch (e1) {}
    try { return String(java.ajax(u)); } catch (e2) { return ''; }
  }
  // 站点 5 秒搜索限流：等一会儿再要一次，别把限流页当无结果
  if (body.indexOf('book-ol') < 0 && body.indexOf('search_challenge') < 0 && body.indexOf('间隔时间') >= 0) {
    body = refetch();
  }
  // 站点当前页所属域名（不写死，方便镜像域/回退域通用）
  function originOf(u) { var m = String(u).match(/^(https?:\/\/[^\/]+)/); return m ? m[1] : String(source.bookSourceUrl).replace(/\/+$/, ''); }
  function pick(h, name) {
    var m = String(h).match(new RegExp('name="' + name + '"[^>]*value="([^"]*)"'));
    return m ? m[1] : '';
  }
  function isCap(h) { return String(h).indexOf('search_challenge') >= 0; }
  function parseList(h) {
    java.setContent(h);
    return java.getElement('ol.book-ol.book-ol-normal li.book-li');
  }
  // ===== 命中站点图形验证码：弹阅读内置「验证码输入框」，填完自动继续本次搜索 =====
  if (isCap(body)) {
    var B = originOf(baseUrl);
    var kk = pick(body, 'searchkey');
    if (!kk) { try { kk = String(java.get('blnKey') || ''); } catch (e) {} }
    var code = '', cid = '', img = '', probe = '', tries = 0, r = [];
    while (tries < 3 && isCap(body)) {
      tries++;
      cid = pick(body, 'search_challenge');
      if (!cid) break;
      var stype = pick(body, 'searchtype') || 'all';
      img = B + '/checkcode.php?scope=search&module=article&id=' + encodeURIComponent(cid) + '&r=' + new Date().getTime();
      // 预取一次：①确认这份会话能取到真图（弹窗用 Glide 走同一套 Cookie）②给弹窗缓存图片
      try { probe = String(java.ajax(img)); } catch (e) { probe = ''; }
      if (probe.length < 200) {
        // 取不到真图就直接引导浏览器过码，别让人对着空白框猜
        try {
          java.startBrowser(B + '/search.html?searchkey=' + encodeURIComponent(kk), '搜索验证·过码后回阅读重搜');
          java.toast('验证码图片加载失败：已在浏览器打开验证页，过码后回阅读重新搜索');
        } catch (e2) {}
        return [];
      }
      try {
        code = String(java.getVerificationCode(img));
      } catch (e) {
        java.toast('已取消验证：可重新搜索，或在书源菜单“登录”里过码');
        return [];
      }
      if (!code || code == 'null') { java.toast('未输入验证码'); return []; }
      // 提交：站点对“验证并搜索”的响应正文本身就是搜索结果页 → 直接继续解析
      body = String(java.ajax(B + '/search.html,' + JSON.stringify({
        method: 'POST',
        body: 'searchkey=' + encodeURIComponent(kk) + '&searchtype=' + encodeURIComponent(stype)
              + '&search_challenge=' + encodeURIComponent(cid) + '&search_code=' + encodeURIComponent(code)
      })));
      if (isCap(body)) { java.toast('验证码不正确，请重新输入（第' + tries + '次）'); }
      else if (body.indexOf('间隔时间') >= 0) { body = refetch(); }
    }
    if (body.indexOf('book-ol') < 0) { java.toast('搜索验证未通过，请再试一次'); return []; }
    r = parseList(body);
    result = body;
  } else if (body.indexOf('book-ol') >= 0) {
    r = parseList(body);
  } else {
    r = [];
  }
  // ===== 记录站点自身总页数，供 searchUrl 终止翻页（不写死上限）=====
  var kw = '';
  try { kw = String(java.get('blnKey') || ''); } catch (e) {}
  var m = body.match(/第\s*\d+\s*\/\s*(\d+)\s*页/);
  var pages = 0;
  if (m) { pages = parseInt(m[1], 10);
  } else { var rr = body.match(/相关共有\s*(\d+)\s*条记录/); if (rr) { pages = Math.ceil(parseInt(rr[1], 10) / 30); } }
  if (pages > 0 && kw && kw != 'null') {
    try { java.put('blnP_' + kw, String(pages)); } catch (e) {}
    try { source.put('blnP_' + kw, String(pages)); } catch (e2) {}
  }
  if (r.length > 0) { return r; }
  if (body.indexOf('book-ol') >= 0) { return r; }
  // ===== 兜底：精确命中时站点直接 302 到详情页，用 og 元数据合成一条卡片 =====
  var doc = org.jsoup.Jsoup.parse(body);
  var g = function(sel) { var e = doc.select(sel); return e.size() > 0 ? e.first().attr('content') : ''; };
  var name = g('meta[property=og:novel:book_name]');
  if (!name) { return []; }
  var esc = function(x) { return String(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
  var card = '<li class="book-li"><a href="' + baseUrl + '"><div class="book-cover"><img data-src="'
    + esc(g('meta[property=og:image]')) + '"></div><h4 class="book-title">' + esc(name)
    + '</h4><p class="book-desc">' + esc(g('meta[property=og:description]'))
    + '</p><span class="book-author">作者' + esc(g('meta[property=og:novel:author]'))
    + '</span><span class="tag-small-group"><em class="tag-small">'
    + esc(g('meta[property=og:novel:category]')) + '</em></span></a></li>';
  java.setContent(card);
  return java.getElement('li.book-li');
})()

